type RayClusterFleet struct {
	metav1.TypeMeta   `json:",inline"`
	metav1.ObjectMeta `json:"metadata,omitempty"`

	Spec   RayClusterFleetSpec   `json:"spec,omitempty"`
	Status RayClusterFleetStatus `json:"status,omitempty"`
}

