				*metav1.NewControllerRef(d, controllerKind),
			},
		},
		Spec: orchestrationv1alpha1.RayClusterReplicaSetSpec{
			Replicas: d.Spec.Replicas,
			Template: d.Spec.Template,
			Selector: d.Spec.Selector,
		},
	}

	if err := r.Create(ctx, newRS); err != nil {
		return nil, err
	}

	return newRS, nil
