35	type rayClusterOrderRule func(a, b *rayclusterv1.RayCluster) int
36	
37	const (
38		rayClusterOrderBefore = -1
39		rayClusterOrderSame   = 0
40		rayClusterOrderAfter  = 1
41	)
42	
43	// NewCondition creates a new replicaset condition.
44	func NewCondition(condType string, status metav1.ConditionStatus, reason, msg string) metav1.Condition {
45		return metav1.Condition{
46			Type:               condType,
47			Status:             status,
48			LastTransitionTime: metav1.Now(),
49			Reason:             reason,
50			Message:            msg,
51		}
52	}
53	
54	// GetCondition returns a replicaset condition with the provided type if it exists.
55	func GetCondition(status orchestrationv1alpha1.RayClusterReplicaSetStatus, condType string) *metav1.Condition {
56		for _, c := range status.Conditions {
57			if c.Type == condType {
58				return &c
59			}
60		}
61		return nil
62	}
63	
64	// SetCondition adds/replaces the given condition in the replicaset status. If the condition that we
65	// are about to add already exists and has the same status and reason then we are not going to update.
66	func SetCondition(status *orchestrationv1alpha1.RayClusterReplicaSetStatus, condition metav1.Condition) {
67		currentCond := GetCondition(*status, condition.Type)
68		if currentCond != nil && currentCond.Status == condition.Status && currentCond.Reason == condition.Reason {
69			return
70		}
71		newConditions := filterOutCondition(status.Conditions, condition.Type)
72		status.Conditions = append(newConditions, condition)
73	}
74	
75	// RemoveCondition removes the condition with the provided type from the replicaset status.
76	func RemoveCondition(status *orchestrationv1alpha1.RayClusterReplicaSetStatus, condType string) {
77		status.Conditions = filterOutCondition(status.Conditions, condType)
78	}
79	
80	// filterOutCondition returns a new slice of replicaset conditions without conditions with the provided type.
81	func filterOutCondition(conditions []metav1.Condition, condType string) []metav1.Condition {
82		var newConditions []metav1.Condition
83		for _, c := range conditions {
84			if c.Type == condType {
85				continue
86			}
87			newConditions = append(newConditions, c)
88		}
89		return newConditions
90	}
91	
92	// Helper function to construct a new Pod from a ReplicaSet
93	func constructRayCluster(replicaset *orchestrationv1alpha1.RayClusterReplicaSet) *rayclusterv1.RayCluster {
94		cluster := &rayclusterv1.RayCluster{
95			ObjectMeta: metav1.ObjectMeta{
96				GenerateName: replicaset.Name + "-",
97				Namespace:    replicaset.Namespace,
98				Labels:       replicaset.Spec.Template.Labels,
99				Annotations:  replicaset.Spec.Template.Annotations,
100				OwnerReferences: []metav1.OwnerReference{
101					*metav1.NewControllerRef(replicaset, controllerKind),
102				},
103			},
104			Spec: replicaset.Spec.Template.Spec,
105		}
106	
107		return cluster
108	}
109	
110	// filterActiveClusters filters out inactive Cluster from a list of RayClusters
111	func filterActiveClusters(clusters []rayclusterv1.RayCluster) []rayclusterv1.RayCluster {
112		activeClusters := make([]rayclusterv1.RayCluster, 0)
113		for _, cluster := range clusters {
114			if isClusterActive(cluster) {
115				activeClusters = append(activeClusters, cluster)
116			} else {
117				klog.V(4).Info("Ignore inactive cluster", "name", cluster.Name, "state", cluster.Status.State, "deletionTime", cluster.DeletionTimestamp)
118			}
119	
120		}
121	
122		return activeClusters
123	}
124	
125	func sortRayClustersForScaleDown(clusters []rayclusterv1.RayCluster) {
126		sortRayClustersByRules(
127			clusters,
128			orderRayClusterNotReadyBeforeReady,
129			orderRayClusterLowerDeletionCostBeforeHigher,
130			orderRayClusterOlderCreationTimestampBeforeNewer,
131			orderRayClusterNamespacedName,
132		)
133	}
134	
135	func sortRayClustersByRules(clusters []rayclusterv1.RayCluster, rules ...rayClusterOrderRule) {
136		sort.SliceStable(clusters, func(i, j int) bool {
137			for _, rule := range rules {
138				switch rule(&clusters[i], &clusters[j]) {
139				case rayClusterOrderBefore:
140					return true
141				case rayClusterOrderAfter:
142					return false
143				}
144			}
145			return false
146		})
147	}
148	
149	func orderRayClusterNotReadyBeforeReady(a, b *rayclusterv1.RayCluster) int {
150		aReady := rayclusterutil.IsRayClusterReady(a)
151		bReady := rayclusterutil.IsRayClusterReady(b)
152		if aReady == bReady {
153			return rayClusterOrderSame
154		}
155		if !aReady && bReady {
156			return rayClusterOrderBefore
157		}
158		return rayClusterOrderAfter
159	}
160	
161	func orderRayClusterLowerDeletionCostBeforeHigher(a, b *rayclusterv1.RayCluster) int {
162		aCost := getRayClusterDeletionCost(a)
163		bCost := getRayClusterDeletionCost(b)
164		if aCost == bCost {
165			return rayClusterOrderSame
166		}
167		if aCost < bCost {
168			return rayClusterOrderBefore
169		}
170		return rayClusterOrderAfter
171	}
172	
173	func orderRayClusterOlderCreationTimestampBeforeNewer(a, b *rayclusterv1.RayCluster) int {
174		if a.CreationTimestamp.Equal(&b.CreationTimestamp) {
175			return rayClusterOrderSame
176		}
177		if a.CreationTimestamp.Before(&b.CreationTimestamp) {
178			return rayClusterOrderBefore
179		}
180		return rayClusterOrderAfter
181	}
182	
183	func orderRayClusterNamespacedName(a, b *rayclusterv1.RayCluster) int {
184		if a.Namespace != b.Namespace {
185			if a.Namespace < b.Namespace {
186				return rayClusterOrderBefore
187			}
188			return rayClusterOrderAfter
189		}
190		if a.Name == b.Name {
191			return rayClusterOrderSame
192		}
193		if a.Name < b.Name {
194			return rayClusterOrderBefore
195		}
196		return rayClusterOrderAfter
197	}
198	
199	func getRayClusterDeletionCost(cluster *rayclusterv1.RayCluster) int {
200		if cluster == nil || cluster.Annotations == nil {
201			return 0
202		}
203		cost, err := strconv.Atoi(cluster.Annotations[rayClusterDeletionCostAnnotation])
204		if err != nil {
205			return 0
206		}
207		return cost
208	}
209	
210	func isClusterActive(c rayclusterv1.RayCluster) bool {
211		// Case 1: This RayCluster has been marked for deletion.
212		if !c.DeletionTimestamp.IsZero() {
213			return false
214		}
215	
216		// Case 2: The RayCluster has not been provisioned yet.
217		// This means the RayCluster is in the init stage, waiting for all Ray Pods to become ready for the first time.
218		// We consider the RayCluster active, as the ReplicaSet also counts Pods that are in the init stage.
219		isRayClusterProvisioned := meta.IsStatusConditionPresentAndEqual(c.Status.Conditions, string(rayclusterv1.RayClusterProvisioned), metav1.ConditionTrue)
220		if !isRayClusterProvisioned {
221			return true
222		}
223	
224		// Case 3: The RayCluster has been provisioned and we need to check if it is ready.
225		// Currently, we consider any Ray Pod failure is unrecoverable and need to recreate a new RayCluster.
226		return rayclusterutil.IsRayClusterReady(&c)
227	}
228	
229	func isStatusSame(rs *orchestrationv1alpha1.RayClusterReplicaSet, newStatus orchestrationv1alpha1.RayClusterReplicaSetStatus) bool {
230		// Only update the status if something has actually changed
231		if rs.Status.Replicas == newStatus.Replicas &&
232			rs.Status.FullyLabeledReplicas == newStatus.FullyLabeledReplicas &&
233			rs.Status.ReadyReplicas == newStatus.ReadyReplicas &&
234			rs.Status.AvailableReplicas == newStatus.AvailableReplicas &&
235			rs.Generation == rs.Status.ObservedGeneration &&
236			reflect.DeepEqual(rs.Status.Conditions, newStatus.Conditions) {
237			return true
238		}
239	
240		return false
241	}
242	
243	func calculateStatus(rs *orchestrationv1alpha1.RayClusterReplicaSet, filteredClusters []rayclusterv1.RayCluster, manageReplicasErr error) orchestrationv1alpha1.RayClusterReplicaSetStatus {
244		newStatus := rs.Status
245		// Count the number of pods that have labels matching the labels of the cluster
246		// template of the replica set, the matching pods may have more
247		// labels than are in the template. Because the label of podTemplateSpec is
248		// a superset of the selector of the replica set, so the possible
249		// matching pods must be part of the filteredClusters.
250		fullyLabeledReplicasCount := 0
251		readyReplicasCount := 0
252		availableReplicasCount := 0
253		templateLabel := labels.Set(rs.Spec.Template.Labels).AsSelectorPreValidated()
254		for _, cluster := range filteredClusters {
255			if templateLabel.Matches(labels.Set(cluster.Labels)) {
256				fullyLabeledReplicasCount++
257			}
258			if rayclusterutil.IsRayClusterReady(&cluster) {
259				readyReplicasCount++
260				if rayclusterutil.IsRayClusterAvailable(&cluster, rs.Spec.MinReadySeconds, metav1.Now()) {
261					availableReplicasCount++
262				}
263			}
264		}
265	
266		failureCond := GetCondition(rs.Status, orchestrationv1alpha1.RayClusterReplicaSetReplicaFailure)
267		if manageReplicasErr != nil && failureCond == nil {
268			var reason string
269			if diff := len(filteredClusters) - int(*(rs.Spec.Replicas)); diff < 0 {
270				reason = "FailedCreate"
271			} else if diff > 0 {
272				reason = "FailedDelete"
273			}
274			cond := NewCondition(orchestrationv1alpha1.RayClusterReplicaSetReplicaFailure, metav1.ConditionTrue, reason, manageReplicasErr.Error())
275			SetCondition(&newStatus, cond)
276		} else if manageReplicasErr == nil && failureCond != nil {
277			RemoveCondition(&newStatus, orchestrationv1alpha1.RayClusterReplicaSetReplicaFailure)
278		}
279	
280		newStatus.Replicas = int32(len(filteredClusters))
281		newStatus.FullyLabeledReplicas = int32(fullyLabeledReplicasCount)
282		newStatus.ReadyReplicas = int32(readyReplicasCount)
283		newStatus.AvailableReplicas = int32(availableReplicasCount)
284	
285		return newStatus
286	}
